using System.IO;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using TextureFlow;
class Tests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 [STAThread] static int Main(string[] args){if(args.Length>1&&args[1]=="--live")return VoidLiveTests.Run(Path.GetFullPath(args[0]));var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int code=0;app.Startup+=async(_,_)=>{MainWindow? owner=null;SkyboxVoidTab? tab=null;try{
 string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root+"/Assets");Directory.CreateDirectory(root+"/ProjectSettings");
 var hashes=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText("compatibility/legacy-0.3.0-sha256.json"))!;foreach(var pair in hashes)Check(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(pair.Key))).Equals(pair.Value,StringComparison.OrdinalIgnoreCase),"unchanged "+pair.Key);
 owner=new MainWindow();owner.Show();await Task.Delay(100);Check(owner.Content is TabControl outer&&outer.Items.Count==2,"two outer tabs automatically attached");var tabs=(TabControl)owner.Content;tabs.SelectedIndex=1;await Task.Delay(100);tab=(SkyboxVoidTab)((TabItem)tabs.Items[1]).Content;tab.SetActive(false);tab.LoadExample();tab.Tools.VoidProject=root;tab.SetActive(true);await Task.Delay(800);tab.SetActive(false);var shot=new System.Windows.Media.Imaging.RenderTargetBitmap((int)owner.ActualWidth,(int)owner.ActualHeight,96,96,System.Windows.Media.PixelFormats.Pbgra32);shot.Render(owner);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(shot));using(var output=File.Create(root+"/void-desktop-preview.png"))png.Save(output);Check(tab.Tools.Content is DockPanel,"painting tools are original editor without nested new tabs");
 var w=tab.Tools.VoidSnapshot();Check(w.Layers.Length==1&&w.Layers[0].Mask.Any(x=>x==255)&&w.Layers[0].Mask.Any(x=>x==0),"example has bounded opening");
 var frames=new[]{new VoidFrame(w.Layers[0].Flow!,w.Layers[0].Mask,new VoidLookSettings())};var a=VoidPreview.Render(w.Original,frames,0,0,0,128);var b=VoidPreview.Render(w.Original,frames,0,30,0,128);Check(!a.Pixels.SequenceEqual(b.Pixels),"sky responds to view direction");Check(a.Pixels.Take(4).SequenceEqual(b.Pixels.Take(4)),"outside opening stays fixed");var c=VoidPreview.Render(w.Original,frames,10,0,0,128);Check(!a.Pixels.SequenceEqual(c.Pixels),"sky animates with time");
 frames[0]=frames[0] with {Look=VoidLookSettings.Preset(1)};a=VoidPreview.Render(w.Original,frames,0,0,0,128);b=VoidPreview.Render(w.Original,frames,0,30,0,128);Check(!a.Pixels.SequenceEqual(b.Pixels),"void parallax responds to view");frames[0].Look.depth=1.8f;c=VoidPreview.Render(w.Original,frames,0,30,0,128);Check(!b.Pixels.SequenceEqual(c.Pixels),"depth changes void projection");frames[0]=frames[0] with {Look=VoidLookSettings.Preset(2)};c=VoidPreview.Render(w.Original,frames,0,30,0,128);Check(!b.Pixels.SequenceEqual(c.Pixels),"tunnel differs from void");
 ((ComboBox)typeof(SkyboxVoidTab).GetField("StyleChoice",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(tab)!).SelectedIndex=2;string save=root+"/test.voidflow";await tab.SaveVoidAsync(save);tab.LoadExample();await tab.LoadVoidAsync(save);Check(tab.LookFor(tab.Tools.VoidArea!).style==2,"own save/open preserves look");Check(tab.Tools.VoidSnapshot().Layers[0].Mask.SequenceEqual(w.Layers[0].Mask),"save/open keeps editable mask");
 string dir=await tab.ExportVoidAsync();Check(File.Exists(dir+"/void-request.json")&&!File.Exists(dir+"/flow-request.json"),"separate export request");Check(File.Exists(root+"/Assets/TextureFlow/Companion/Editor/VoidBridge.cs"),"automatic additive companion setup");
 bool rejected=false;try{VoidFiles.Inside(root,"../outside");}catch(IOException){rejected=true;}Check(rejected,"traversal rejected");
 var before=w.Original.Pixels.ToArray();var copied=tab.Tools.VoidSnapshot();owner.VoidCopyFrom(copied);owner.VoidWholeOpening();Check(tab.Tools.VoidSnapshot().Layers[0].Mask.SequenceEqual(w.Layers[0].Mask),"mask workspaces independent");Check(w.Original.Pixels.SequenceEqual(before),"source pixels preserved");
 var field=typeof(MainWindow).GetField("Steps",BindingFlags.Instance|BindingFlags.NonPublic)!;Check(((TabControl)field.GetValue(owner)!).Items.Count==3,"original three steps retained");
 var second=tab.Tools.AddEffectLayer();tab.Tools.VoidWholeOpening();tab.Tools.VoidUseStars();var multi=tab.Tools.VoidSnapshot();var looks=new[]{VoidLookSettings.Preset(0),VoidLookSettings.Preset(2)};var multiDir=VoidFiles.Write(root,multi,looks);var config=JsonSerializer.Deserialize<VoidExport>(File.ReadAllText(multiDir+"/void-request.json"),VoidFiles.Json)!;Check(config.areas.Length==2&&config.areas[0].look.style==0&&config.areas[1].look.style==2&&config.areas[0].maskFile!=config.areas[1].maskFile,"independent openings export distinct looks and masks");tab.Tools.EffectLayers[0].Enabled=false;multiDir=VoidFiles.Write(root,tab.Tools.VoidSnapshot(),looks);config=JsonSerializer.Deserialize<VoidExport>(File.ReadAllText(multiDir+"/void-request.json"),VoidFiles.Json)!;Check(config.areas.Length==1&&config.areas[0].look.style==2,"disabled opening excluded without shifting look mapping");
 File.WriteAllText(root+"/desktop-void-result.txt",count+" checks passed");Console.WriteLine(count+" checks passed");
 }catch(Exception ex){Console.Error.WriteLine(ex);code=1;}finally{tab?.Dispose();owner?.Close();app.Shutdown();}};app.Run();return code;}
}
